let b = {};
try { const w = $('RSS Webhook').first().json; b = (w && (w.body || w)) || {}; } catch (e) { b = {}; }
const slug = typeof b.feed_slug === 'string' && /^[a-z0-9-]{2,60}$/.test(b.feed_slug) ? b.feed_slug : null;
return [{ json: { feed_slug: slug, manual: Boolean(b.action || b.feed_slug) } }];

const p = $('Prepare').first().json;
const cfgRes = $('Fetch Config').first().json || {};
const cfg = (cfgRes.statusCode || 0) < 300 && Array.isArray(cfgRes.body) ? (cfgRes.body[0] || {}) : {};
const fr = $('Fetch Feeds').first().json || {};
const feeds = (fr.statusCode || 0) < 300 && Array.isArray(fr.body) ? fr.body : [];
if (cfg.rss_enabled === false && !p.manual) return [{ json: { skip: true, reason: 'rss_desactivado_en_content_config' } }];
if ((fr.statusCode || 0) >= 300 || !fr.statusCode) return [{ json: { skip: true, reason: 'no_pude_leer_content_feeds', error: true } }];
if (!feeds.length) return [{ json: { skip: true, reason: 'sin_feeds_activos' } }];
return feeds.map((feed) => ({ json: { feed } }));

function rssCanonicalUrl(raw, base) {
  let u = String(raw || '').trim();
  if (!u) return '';
  if (/^\/\//.test(u)) u = 'https:' + u;
  if (!/^https?:\/\//i.test(u)) {
    const m = /^(https?:\/\/[^/]+)/i.exec(String(base || ''));
    if (!m) return '';
    u = m[1] + (u.startsWith('/') ? '' : '/') + u;
  }
  u = u.replace(/#.*$/, '');
  const q = u.indexOf('?');
  let query = '';
  if (q >= 0) {
    const keep = u.slice(q + 1).split('&').filter((p) => p && !/^(utm_[a-z]+|fbclid|gclid|mc_cid|mc_eid|ref|source)=/i.test(p));
    query = keep.length ? '?' + keep.join('&') : '';
    u = u.slice(0, q);
  }
  return u.replace(/\/+$/, '') + query;
}

function rssFeedHealth(feed, res, parsed, nowIso) {
  const f = feed || {};
  const code = Number(res && res.statusCode);
  let error = null;
  if (!res || res.error || !Number.isFinite(code)) error = 'sin_respuesta';
  else if (code < 200 || code >= 300) error = 'http_' + code;
  else if (parsed && parsed.error) error = parsed.error;
  else if (parsed && !parsed.items.length) error = 'feed_sin_articulos';
  const failures = error ? (Number(f.consecutive_failures) || 0) + 1 : 0;
  return { last_checked_at: nowIso, last_status: error ? 'error' : 'ok', last_error: error, last_item_count: parsed ? parsed.items.length : 0, consecutive_failures: failures };
}

function rssFnv(text) {
  const s = String(text || '');
  let h = 0x811c9dc5;
  for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 0x01000193) >>> 0; }
  return h.toString(16).padStart(8, '0');
}

function rssItemHash(item) {
  const key = String((item && (item.guid || item.url)) || '').trim().toLowerCase();
  return rssFnv(key);
}

function rssParseFeed(xml, opts) {
  const o = opts || {};
  const limit = o.limit || 30;
  const src = String(xml || '').slice(0, o.maxChars || 600000);
  if (!/<(rss|feed|rdf:RDF)\b/i.test(src)) return { format: null, items: [], error: 'no_es_feed_rss_ni_atom' };
  const atom = /<feed\b/i.test(src) && !/<rss\b/i.test(src);
  const blocks = src.match(atom ? /<entry\b[\s\S]*?<\/entry>/gi : /<item\b[\s\S]*?<\/item>/gi) || [];
  const tag = (blk, names) => {
    for (const n of names) {
      const m = new RegExp('<' + n + '(?:\\s[^>]*)?>([\\s\\S]*?)</' + n + '>', 'i').exec(blk);
      if (m) return m[1];
    }
    return '';
  };
  const items = [];
  for (const blk of blocks) {
    const title = rssPlain(tag(blk, ['title']), 200);
    let link = '';
    if (atom) {
      const links = blk.match(/<link\b[^>]*>/gi) || [];
      const alt = links.find((l) => /rel=["']alternate["']/i.test(l)) || links.find((l) => !/rel=/i.test(l)) || links[0] || '';
      const h = /href=["']([^"']+)["']/i.exec(alt);
      link = h ? h[1] : '';
    } else {
      link = rssPlain(tag(blk, ['link']), 600);
      if (!link) { const h = /<link\b[^>]*href=["']([^"']+)["']/i.exec(blk); link = h ? h[1] : ''; }
    }
    link = link.replace(/&amp;/g, '&');
    const url = rssCanonicalUrl(link, o.base);
    const guid = rssPlain(tag(blk, ['guid', 'id']), 300);
    const summary = rssPlain(tag(blk, ['content:encoded', 'description', 'summary', 'content']), o.summaryChars || 700);
    const dateRaw = rssPlain(tag(blk, ['pubDate', 'published', 'updated', 'dc:date']), 80);
    const t = dateRaw ? Date.parse(dateRaw) : NaN;
    if (!title || !url) continue;
    const item = { title, url, guid: guid || url, summary, published_at: Number.isFinite(t) ? new Date(t).toISOString() : null };
    item.hash = rssItemHash(item);
    items.push(item);
  }
  items.sort((a, b) => (Date.parse(b.published_at || 0) || 0) - (Date.parse(a.published_at || 0) || 0));
  return { format: atom ? 'atom' : 'rss', items: items.slice(0, limit) };
}

function rssPlain(raw, max) {
  const named = { amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ', hellip: '…', mdash: '—', ndash: '–', rsquo: '’', lsquo: '‘', rdquo: '”', ldquo: '“' };
  const decode = (t) => t.replace(/&#x([0-9a-f]+);/gi, (m, h) => { const n = parseInt(h, 16); return n > 31 && n < 0x110000 ? String.fromCodePoint(n) : ' '; })
    .replace(/&#(\d+);/g, (m, d) => { const n = parseInt(d, 10); return n > 31 && n < 0x110000 ? String.fromCodePoint(n) : ' '; })
    .replace(/&([a-z]+);/gi, (m, n) => (Object.prototype.hasOwnProperty.call(named, n.toLowerCase()) ? named[n.toLowerCase()] : m));
  const strip = (t) => t.replace(/<script[\s\S]*?<\/script>|<style[\s\S]*?<\/style>/gi, ' ').replace(/<br\s*\/?>|<\/p>|<\/li>|<\/h\d>/gi, ' ').replace(/<[^>]+>/g, ' ');
  let s = String(raw || '').replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1');
  s = decode(strip(s));
  // Feeds con HTML escapado (&lt;p&gt;…): tras decodificar aparece marcado; se limpia una segunda vez.
  if (/<[a-z/][^>]*>/i.test(s)) s = decode(strip(s));
  s = s.replace(/\s+/g, ' ').trim();
  return max && s.length > max ? s.slice(0, max - 1).trimEnd() + '…' : s;
}

function rssRelevance(item) {
  const t = (String((item && item.title) || '') + ' ' + String((item && item.summary) || '')).toLowerCase();
  const strong = ['agent', 'agente', 'automat', 'workflow', 'whatsapp', 'crm', 'mcp', 'n8n', 'integrat', 'integraci', 'voice', 'assistant', 'asistente', 'customer support', 'api', 'webhook', 'supabase', 'tool use', 'function calling', 'zapier', 'no-code', 'low-code', 'small business', 'pyme'];
  const medium = ['claude', 'gpt', 'gemini', 'llm', 'model', 'pricing', 'precio', 'release', 'launch', 'lanza', 'email', 'calendar', 'sales', 'ventas', 'support', 'chatbot', 'enterprise', 'security', 'data'];
  const noise = ['hiring', 'we are hiring', 'podcast', 'webinar', 'award', 'research paper', 'dataset', 'benchmark'];
  let s = 0;
  strong.forEach((k) => { if (t.includes(k)) s += 2; });
  medium.forEach((k) => { if (t.includes(k)) s += 1; });
  noise.forEach((k) => { if (t.includes(k)) s -= 2; });
  return Math.max(0, Math.min(10, s));
}

const MAX_AGE_DAYS = 14;
const feedsIn = $('Expand Feeds').all().map((i) => i.json);
if (feedsIn.length === 1 && feedsIn[0].skip) return [{ json: { writes: [], skipped: feedsIn[0].reason, fatal: feedsIn[0].error === true, meta: [] } }];
const resps = $input.all();
const nowMs = Date.now(), nowIso = new Date(nowMs).toISOString();
const writes = [], meta = [];
const rows = new Map();
feedsIn.forEach((fi, idx) => {
  const feed = fi.feed;
  const r = resps.find((x) => x.pairedItem && x.pairedItem.item === idx) || resps[idx] || { json: {} };
  const res = r.json || {};
  // n8n entrega el texto de la respuesta en data (responseFormat text); body por si cambia.
  const text = typeof res.data === 'string' ? res.data : (typeof res.body === 'string' ? res.body : '');
  let parsed = null;
  if (Number(res.statusCode) >= 200 && Number(res.statusCode) < 300) parsed = text ? rssParseFeed(text, { base: feed.url, limit: 40 }) : { format: null, items: [], error: 'respuesta_vacia' };
  const health = rssFeedHealth(feed, res.error ? { error: true } : res, parsed, nowIso);
  writes.push({ method: 'PATCH', path: 'content_feeds?id=eq.' + feed.id, body: health, prefer: 'return=minimal' });
  let fresh = 0;
  (parsed ? parsed.items : []).forEach((it) => {
    const t = it.published_at ? Date.parse(it.published_at) : null;
    if (t !== null && nowMs - t > MAX_AGE_DAYS * 86400000) return;
    if (t !== null && t - nowMs > 2 * 86400000) return;
    const key = feed.id + ':' + it.hash;
    if (rows.has(key)) return;
    rows.set(key, { feed_id: feed.id, feed_slug: feed.slug, item_hash: it.hash, title: it.title.slice(0, 200), url: it.url, summary: it.summary || null, published_at: it.published_at, relevance: rssRelevance(it), status: 'new' });
    fresh++;
  });
  meta.push({ slug: feed.slug, status: health.last_status, error: health.last_error, found: parsed ? parsed.items.length : 0, fresh, failures: health.consecutive_failures });
});
if (rows.size) writes.push({ method: 'POST', path: 'content_feed_items?on_conflict=feed_id,item_hash', body: Array.from(rows.values()), prefer: 'resolution=ignore-duplicates,return=representation' });
return [{ json: { writes, meta } }];

const w = $('Collect').first().json.writes || [];
if (!w.length) return [{ json: { skip: true } }];
return w.map((x) => ({ json: { skip: false, ...x } }));

const c = $('Collect').first().json;
if (c.fatal) return [{ json: { ok: false, error: c.skipped, safety: { pieces_created: 0, published: 0 } } }];
const applied = $('Apply Writes').all().map((i) => i.json);
const planned = c.writes || [];
const bad = applied.slice(0, planned.length).filter((j, i) => !planned[i] || !j.statusCode || j.statusCode >= 300);
const itemsIdx = planned.findIndex((w) => /^content_feed_items/.test(w.path));
const inserted = itemsIdx >= 0 && Array.isArray((applied[itemsIdx] || {}).body) ? applied[itemsIdx].body : [];
const failed = (c.meta || []).filter((m) => m.status === 'error');
const out = { ok: bad.length === 0 && !c.fatal, skipped: c.skipped || null, feeds_checked: (c.meta || []).length, feeds_ok: (c.meta || []).filter((m) => m.status === 'ok').length, feeds_failed: failed.length,
  failures: failed.map((m) => m.slug + ': ' + m.error + ' (racha ' + m.failures + ')'), new_items: inserted.length,
  new: inserted.slice(0, 25).map((r) => ({ id: r.id, feed: r.feed_slug, title: r.title, url: r.url, relevance: r.relevance, published_at: r.published_at })),
  per_feed: c.meta, safety: { pieces_created: 0, published: 0, note: 'Solo detecta y guarda artículos; Hermes decide si alguno merece una señal.' } };
if (bad.length) out.persist_error = 'Supabase ' + (bad[0].statusCode ? 'HTTP ' + bad[0].statusCode : 'sin respuesta (red)') + ': ' + JSON.stringify(bad[0].body || {}).slice(0, 160);
return [{ json: out }];
